(() => {
  const messageOrigin=location.protocol==='file:'?'*':location.origin;
  const variant=document.body.dataset.variant;
  const params=new URLSearchParams(location.search);
  let language=params.get('lang')==='ru'?'ru':'en';
  const balance=8253;
  const rewards=[
    {id:'ali800',name:'AliExpress Card',face:800,cost:8000},
    {id:'ali3000',name:'AliExpress Card',face:3000,cost:30000},
    {id:'recharge20',name:'Recharge Card',face:20,cost:200}
  ];
  const tasks=[
    {id:'ml',name:'Mobile Legends: Bang Bang',icon:'ML',points:100,state:'completed',progress:100,timer:'23:43:00'},
    {id:'pubg',name:'PUBG Mobile',icon:'PG',points:100,state:'progress',progress:50},
    {id:'cod',name:'Call of Duty',icon:'CD',points:100,state:'new',progress:0},
    {id:'mono',name:'MONOPOLY GO!',icon:'MG',points:null,state:'new',progress:0}
  ];
  const dict={
    en:{history:'History →',guide:'Use your coins toward real rewards.',rewards:'Redeem Rewards',all:'View all',face:'Card placeholder',coins:'Mi Coins',met:'Threshold met',short:'Insufficient coins',missing:'short',choose:'Choose a reward goal',empty:'Select an existing reward to see your progress.',chooseButton:'Choose reward',target:'Reward goal',balance:'Balance',required:'Required',left:'coins to go',view:'View redemption',change:'Change goal',earn:'Earn Mi Coins',download:'Download and Activate',completed:'Completed',progress:'In Progress',new:'Not Started',details:'View task',continue:'Continue',start:'Start task',unknown:'Reward to confirm',timer:'Source timer',noCurrent:'No task in progress.',current:'Current Task Progress',next:'Check the task requirements to continue.',nextGoal:'Complete tasks toward your chosen reward.',select:'Set as goal',close:'Close',rewardDetails:'Reward details',conditions:'Threshold met based on balance only. Stock, regional eligibility and redemption rules require confirmation.',preview:'Prototype preview only. No redemption is submitted.',gapExplain:'The gap uses the original reward threshold. No fixed cash conversion is assumed.',back:'Back',info:'Information',prototype:'Low-fidelity interaction hypothesis · No real transactions',reset:'Reset prototype',source:'Source information',historyTitle:'Coin history',historyBody:'History entry is preserved. The source screenshot does not provide records; no transactions have been invented.',taskBody:'Source requirement: Download and Activate. Detailed steps, eligibility, timing and crediting rules require confirmation.',demo:'Prototype simulation',demoBody:'Change task state only. This does not add coins or imply that rewards are credited automatically.',simulate:'Simulate task completed',demoDone:'Demo state updated. Balance remains 8,253.',goalDone:'Reward goal selected.',original:'Original',method:'Completed is inferred from the checkmark; MONOPOLY GO! reward is cropped and unverified. Timer meaning is unverified.',progressHelp:'50% comes from the source; the exact stage is unverified.'},
    ru:{history:'История →',guide:'Используйте баллы для получения наград.',rewards:'Обменять на награды',all:'Все награды',face:'Место для карты',coins:'Mi Coins',met:'Баллов достаточно',short:'Недостаточно баллов',missing:'не хватает',choose:'Выберите цель для обмена',empty:'Выберите награду, чтобы увидеть прогресс.',chooseButton:'Выбрать награду',target:'Цель обмена',balance:'Баланс',required:'Требуется',left:'баллов до цели',view:'Перейти к обмену',change:'Изменить цель',earn:'Заработать Mi Coins',download:'Скачать и активировать',completed:'Выполнено',progress:'В процессе',new:'Не начато',details:'Подробнее',continue:'Продолжить',start:'Начать задание',unknown:'Награда уточняется',timer:'Таймер на скриншоте',noCurrent:'Нет активного задания.',current:'Текущее задание',next:'Уточните условия, чтобы продолжить задание.',nextGoal:'Выполняйте задания для выбранной награды.',select:'Выбрать целью',close:'Закрыть',rewardDetails:'Информация о награде',conditions:'Достаточность баллов определена по балансу. Наличие награды, региональные ограничения и правила обмена требуют уточнения.',preview:'Только прототип. Обмен не выполняется.',gapExplain:'Разница рассчитана по исходному порогу. Фиксированный курс обмена не предполагается.',back:'Назад',info:'Информация',prototype:'Гипотеза взаимодействия · Без реальных операций',reset:'Сбросить прототип',source:'Исходные данные',historyTitle:'История баллов',historyBody:'Вход в историю сохранён. Записи отсутствуют на исходном скриншоте и не выдуманы.',taskBody:'Исходное условие: скачать и активировать. Подробные шаги, ограничения, сроки и правила начисления требуют уточнения.',demo:'Симуляция прототипа',demoBody:'Меняется только статус задания. Баланс не увеличивается; автоматическое начисление не предполагается.',simulate:'Завершить в демо',demoDone:'Демо-статус обновлён. Баланс: 8,253.',goalDone:'Цель выбрана.',original:'Исходное',method:'Статус «Выполнено» выведен из галочки. Награда MONOPOLY GO! обрезана. Значение таймера не уточнено.',progressHelp:'50% взято со скриншота; точный этап не уточнён.'}
  };
  const t=key=>dict[language][key];
  const fmt=n=>n.toLocaleString('en-US');
  let goal=null;
  const app=document.getElementById('app'),sheet=document.getElementById('sheet');
  let noticeTimer;
  function notice(message){const e=document.getElementById('notice');e.textContent=message;e.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>e.classList.remove('visible'),2400);}
  function rewardButton(reward,index){const enough=balance>=reward.cost;return `<button class="reward ${index===0?'featured':''} ${goal===reward.id?'selected':''}" data-action="reward" data-id="${reward.id}" aria-label="${reward.name}, ${fmt(reward.face)} ₽, ${fmt(reward.cost)} Mi Coins"><span class="reward-art" aria-hidden="true">${t('face')}</span><strong>${reward.name}</strong><span class="face">${fmt(reward.face)} ₽</span><span class="cost">${fmt(reward.cost)} ${t('coins')}</span><span class="eligibility ${enough?'':'insufficient'}">${t(enough?'met':'short')}</span>${!enough?`<span class="difference">${fmt(reward.cost-balance)} ${t('missing')}</span>`:''}</button>`;}
  function goalModule(){const selected=rewards.find(r=>r.id===goal);if(!selected)return `<div class="goal"><h3>${t('choose')}</h3><p>${t('empty')}</p><button data-action="all-rewards">${t('chooseButton')}</button></div>`;const gap=Math.max(0,selected.cost-balance);return `<div class="goal"><h3>${t('target')}</h3><p class="goal-name">${selected.name} · ${fmt(selected.face)} ₽</p><div class="goal-facts"><span>${t('balance')}: ${fmt(balance)}</span><span>${t('required')}: ${fmt(selected.cost)}</span></div><div class="bar" role="progressbar" aria-label="${t('target')}" aria-valuenow="${Math.min(balance,selected.cost)}" aria-valuemin="0" aria-valuemax="${selected.cost}"><span style="width:${Math.min(100,balance/selected.cost*100)}%"></span></div>${gap?`<p class="gap">${fmt(gap)} ${t('left')}</p><p>${t('nextGoal')}</p><button data-action="go-tasks">${t('earn')} ↓</button>`:`<p>${t('met')}</p><button data-action="redeem" data-id="${selected.id}">${t('view')}</button>`}<button class="text-action" data-action="all-rewards">${t('change')}</button></div>`;}
  function rewardsModule(includeGoal){return `<section class="module" id="rewards"><div class="eyebrow">${variant==='A'?'01 / Value':'04 / Value'}</div><div class="module-head"><h2>${t('rewards')}</h2><button data-action="all-rewards">${t('all')} →</button></div><div class="reward-grid">${rewards.map(rewardButton).join('')}</div>${includeGoal?goalModule():''}</section>`;}
  function taskRow(task){const state=task.state==='completed'?'completed':task.state==='progress'?'progress':'new';return `<article class="task"><div class="game-icon" aria-hidden="true">${task.icon}</div><div class="task-copy"><h3>${task.name}</h3><p class="points">${task.points===null?t('unknown'):'+'+task.points+' '+t('coins')}</p><p>${t('download')}</p>${task.timer?`<p class="source-timer">${task.timer} · ${t('timer')}</p>`:''}</div><div class="task-actions"><span class="state ${state==='new'?'not-started':''}">${state==='progress'?'50% · ':''}${t(state)}</span><button data-action="task" data-id="${task.id}">${t(state==='completed'?'details':state==='progress'?'continue':'start')}</button></div></article>`;}
  function tasksModule(){const ordered=variant==='B'?[...tasks.filter(t=>t.state==='progress'),...tasks.filter(t=>t.state==='new'),...tasks.filter(t=>t.state==='completed')]:tasks;return `<section class="module" id="tasks"><div class="eyebrow">${variant==='A'?'02 / Action & Progress':'03 / Action'}</div><div class="module-head"><h2>${t('earn')}</h2></div><div class="task-list">${ordered.map(taskRow).join('')}</div></section>`;}
  function currentModule(){const current=tasks.find(task=>task.state==='progress');return `<section class="module current-task"><div class="eyebrow">02 / Progress</div><h2>${t('current')}</h2>${current?`<h3>${current.name}</h3><p>+${current.points} ${t('coins')} · ${t('download')}</p><div class="progress-line"><span>${t('progress')}</span><strong>50%</strong></div><div class="bar" role="progressbar" aria-label="${current.name}" aria-valuenow="50" aria-valuemin="0" aria-valuemax="100"><span style="width:50%"></span></div><p class="hint">${t('progressHelp')}</p><button data-action="task" data-id="${current.id}">${t('continue')}</button>`:`<p>${t('noCurrent')}</p><button data-action="go-tasks">${t('earn')}</button>`}</section>`;}
  function render(){document.documentElement.lang=language;document.body.classList.toggle('variant-b',variant==='B');app.innerHTML=`<div class="statusbar"><span>2:36</span><span aria-hidden="true">▰ ▰ 100%</span></div><nav class="navigation" aria-label="Mi Coins"><button data-action="back" aria-label="${t('back')}">←</button><h1>Mi Coins</h1><button data-action="info" aria-label="${t('info')}">ⓘ</button></nav><header class="coin-hero"><small>${t('balance')}</small><strong>${fmt(balance)} <span>Mi Coins</span></strong><button class="history" data-action="history">${t('history')}</button><p>${t('guide')}</p><div class="coin-placeholder" aria-hidden="true">COIN<br>ART</div></header><div class="content">${variant==='A'?rewardsModule(true)+tasksModule():currentModule()+tasksModule()+rewardsModule(false)+`<section class="module"><div class="eyebrow">05 / Reward Guidance</div>${goalModule()}</section>`}</div><footer class="prototype-footer">${variant} · 392 × 871 dp · ${t('prototype')}<button data-action="reset">${t('reset')}</button></footer>`;reportHeight();}
  function show(title,body){sheet.innerHTML=`<div class="sheet-header"><h2 id="sheet-title">${title}</h2><button data-action="close" aria-label="${t('close')}">×</button></div><div class="sheet-content">${body}</div>`;sheet.showModal();sheet.querySelector('button')?.focus();}
  function rewardSheet(id){const reward=rewards.find(r=>r.id===id);show(t('rewardDetails'),`<h3>${reward.name} · ${fmt(reward.face)} ₽</h3><dl><dt>${t('required')}</dt><dd>${fmt(reward.cost)} Mi Coins</dd><dt>${t('balance')}</dt><dd>${fmt(balance)} Mi Coins</dd><dt>${t(balance>=reward.cost?'met':'short')}</dt><dd>${fmt(Math.max(0,reward.cost-balance))} ${t('left')}</dd></dl><p>${t('gapExplain')}</p><button class="primary" data-action="select-goal" data-id="${id}">${t('select')}</button>${balance>=reward.cost?`<button class="secondary" data-action="redeem" data-id="${id}">${t('view')}</button>`:''}`);}
  function taskSheet(id){const task=tasks.find(r=>r.id===id);show(task.name,`<p><strong>${task.points===null?t('unknown'):'+'+task.points+' Mi Coins'} · ${t(task.state==='completed'?'completed':task.state==='progress'?'progress':'new')}</strong></p><p>${t('taskBody')}</p>${task.state==='progress'?`<p>${t('progressHelp')}</p>`:''}<div class="demo-controls"><strong>${t('demo')}</strong><p>${t('demoBody')}</p>${task.state!=='completed'?`<button data-action="simulate" data-id="${id}">${t('simulate')}</button>`:''}</div>`);}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;
    if(action==='close'){sheet.close();return;}
    if(action==='reward'){rewardSheet(id);return;}
    if(action==='all-rewards'){show(t('all'),`<div class="sheet-list">${rewards.map(r=>`<button data-action="reward" data-id="${r.id}">${r.name} · ${fmt(r.face)} ₽<br>${fmt(r.cost)} Mi Coins · ${t(balance>=r.cost?'met':'short')}</button>`).join('')}</div>`);return;}
    if(action==='select-goal'){goal=id;sheet.close();render();notice(t('goalDone'));return;}
    if(action==='redeem'){const reward=rewards.find(r=>r.id===id);if(balance<reward.cost)return;show(t('view'),`<h3>${reward.name} · ${fmt(reward.face)} ₽</h3><p>${t('conditions')}</p><p><strong>${t('preview')}</strong></p>`);return;}
    if(action==='task'){taskSheet(id);return;}
    if(action==='simulate'){const task=tasks.find(t=>t.id===id);task.state='completed';task.progress=100;sheet.close();render();notice(t('demoDone'));return;}
    if(action==='history'){show(t('historyTitle'),`<p>${t('historyBody')}</p>`);return;}
    if(action==='info'){show(t('source'),`<p>${t('method')}</p><p>${t('conditions')}</p><p>${t('prototype')}</p>`);return;}
    if(action==='go-tasks'){document.getElementById('tasks').scrollIntoView({behavior:'smooth'});return;}
    if(action==='back'){if(sheet.open)sheet.close();else if(parent!==window)parent.postMessage({type:'mi-wireframe-back'},messageOrigin);else location.href='../index.html#wireframes';return;}
    if(action==='reset'){goal=null;tasks.forEach(task=>{task.state=task.id==='ml'?'completed':task.id==='pubg'?'progress':'new';task.progress=task.id==='ml'?100:task.id==='pubg'?50:0;});render();window.scrollTo(0,0);}
  });
  sheet.addEventListener('click',event=>{if(event.target!==sheet)return;const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();});
  function reportHeight(){if(parent!==window)parent.postMessage({type:'mi-wireframe-height',variant,height:Math.ceil(app.getBoundingClientRect().height)},messageOrigin);}
  addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='mi-wireframe-language'&&['en','ru'].includes(event.data.lang)){language=event.data.lang;if(sheet.open)sheet.close();render();}});
  new ResizeObserver(reportHeight).observe(app);
  render();
})();
